/* Project conversation: real Codex replies, durable history, no workflow mutations. */
(()=>{
 let panel=null,toggle=null,poll=0,busy=false,chat={messages:[],status:'idle'};
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 async function api(body){const options={credentials:'same-origin',cache:'no-store'};if(body){const auth=await(await fetch('/api/agents/token',{headers:{'X-Makora-Request':'token'}})).json();options.method='POST';options.headers={'Content-Type':'application/json','X-Makora-Token':auth.result.token};options.body=JSON.stringify(body)}const response=await fetch('/api/preparation/chat',options),data=await response.json();if(!response.ok)throw Error(data.error?.message||'Не удалось связаться с Макорой');return data.result}
 function position(){const root=document.querySelector('#first-stage'),mascot=root?.querySelector('.mascot-area');if(!mascot||!toggle)return;const r=mascot.getBoundingClientRect();const intro=!root.classList.contains('departing');toggle.style.left=Math.max(12,Math.min(innerWidth-174,intro?r.right+14:r.left+r.width/2-81))+'px';toggle.style.top=Math.min(innerHeight-42,intro?r.top+36:r.bottom+12)+'px';if(panel?.isConnected){const w=Math.min(370,innerWidth-24),left=Math.max(12,Math.min(innerWidth-w-12,r.left+r.width/2-w/2)),top=Math.max(90,Math.min(innerHeight-270,r.bottom+54));Object.assign(panel.style,{left:left+'px',top:top+'px',maxHeight:Math.max(240,innerHeight-top-16)+'px'});panel.style.setProperty('--chat-anchor',Math.max(20,Math.min(w-20,r.left+r.width/2-left))+'px')}}
 function render(){if(!panel?.isConnected)return;const log=panel.querySelector('.project-chat-log'),nearBottom=log.scrollHeight-log.scrollTop-log.clientHeight<60;
  log.innerHTML=chat.messages.length?chat.messages.map(m=>`<article class="chat-message chat-${m.role==='user'?'user':'assistant'}"><small>${m.role==='user'?'Вы':'Макора'}</small><div>${typeof window.render==='function'?window.render(m.text):esc(m.text).replace(/\n/g,'<br>')}</div></article>`).join(''):'<div class="chat-welcome"><h3>Что обсудим?</h3><p>Спроси о задании, документах или следующих шагах. Я вижу контекст проекта.</p></div>';
  const waiting=['sending','running','unconfirmed'].includes(chat.status);panel.querySelector('.project-chat-status').textContent=chat.error||(waiting?'Макора думает…':'GPT-6 Luna · контекст проекта');panel.querySelector('[type=submit]').disabled=busy||waiting;panel.querySelector('textarea').disabled=busy||waiting;panel.querySelector('.project-chat-check').hidden=chat.status!=='unconfirmed'&&chat.status!=='failed';
  if(nearBottom)log.scrollTop=log.scrollHeight;clearTimeout(poll);if(waiting)poll=setTimeout(refresh,1800);
 }
 async function refresh(){try{chat=await api();render()}catch(e){if(panel?.isConnected){panel.querySelector('.project-chat-status').textContent=e.message;clearTimeout(poll);poll=setTimeout(refresh,4000)}}}
 function close(){document.querySelector('#first-stage')?.classList.remove('project-chat-open');panel?.remove();panel=null;clearTimeout(poll);toggle?.setAttribute('aria-expanded','false')}
 async function open(){if(panel?.isConnected){close();return}const root=document.querySelector('#first-stage');if(new URLSearchParams(location.search).has('new')&&root.querySelector('[data-choose-project-folder]')?.dataset.folderSelected!=='true'){const error=root.querySelector('.first-error');error.textContent='Выберите папку нового проекта, затем откройте чат с Макорой.';error.hidden=false;root.querySelector('[data-choose-project-folder]').focus();return}root.querySelector('.analysis-chat')?.remove();panel=document.createElement('form');panel.className='analysis-chat project-chat';panel.setAttribute('aria-label','Чат с Макорой');panel.innerHTML='<div class="speech-label"><span class="analysis-chat-speaker"><i aria-hidden="true"></i> МАКОРА · ЧАТ</span><button type="button" data-chat-close aria-label="Закрыть чат">×</button></div><div class="project-chat-log" role="log" aria-live="polite"></div><div class="project-chat-status" role="status">Загружаем историю…</div><button type="button" class="project-chat-check rp-text-button" hidden>Проверить ответ ↻</button><div class="project-chat-composer"><textarea placeholder="Напиши Макоре…" aria-label="Сообщение Макоре" maxlength="12000"></textarea><button class="rp-primary" type="submit" disabled aria-label="Отправить сообщение">↑</button></div>';
  root.classList.add('project-chat-open');root.append(panel);toggle.setAttribute('aria-expanded','true');position();panel.querySelector('[data-chat-close]').onclick=close;panel.querySelector('.project-chat-check').onclick=refresh;
  panel.onsubmit=async e=>{e.preventDefault();const input=panel.querySelector('textarea'),text=input.value.trim();if(busy||!text||['sending','running','unconfirmed'].includes(chat.status))return;busy=true;panel.querySelector('[type=submit]').disabled=true;panel.querySelector('.project-chat-status').textContent='Отправляем сообщение…';try{chat=await api({message:text,requestId:crypto.randomUUID()});input.value='';render()}catch(e){panel.querySelector('.project-chat-status').textContent=e.message;await refresh()}finally{busy=false;if(panel?.isConnected){render();if(chat.status==='idle')input.focus()}}};
  panel.querySelector('textarea').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();panel.requestSubmit()}};await refresh();if(panel?.isConnected)panel.querySelector('textarea').focus();
 }
 function mount(){const root=document.querySelector('#first-stage');if(!root||toggle?.isConnected)return;toggle=document.createElement('button');toggle.className='makora-chat-toggle';toggle.type='button';toggle.textContent='Поговорить с Макорой';toggle.setAttribute('aria-expanded','false');toggle.onclick=open;root.append(toggle);position()}
 window.makoraChat={open,close};window.addEventListener('makora:mascot-move',position);window.addEventListener('resize',position);window.addEventListener('makora:project-folder',()=>{chat={messages:[],status:'idle'};close()});setInterval(()=>{mount();position()},500);mount();
})();
